package com.crewbeat.hondabox.tests;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import com.crewbeat.hondabox.*;
/** Window-width regression: real layouts, long titles, retained data and all controls visible. No CAN commands. */
public final class PlayerResponsiveTests extends Instrumentation {
 private final ProbeState state=ProbeState.INSTANCE;private Activity activity;private int checks;
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 private Object field(String name)throws Exception{java.lang.reflect.Field f=activity.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(activity);}
 private void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
 private void frame(int type,int... p){int[] a=new int[p.length+4];a[0]=46;a[1]=type;a[2]=p.length;int sum=type+p.length;for(int i=0;i<p.length;i++){a[i+3]=p[i];sum+=p[i];}a[a.length-1]=255-(sum&255);state.event(1019,a,null,null);}
 private void seed(int mode){state.newSession();state.running(true);state.recording(false);state.status("test","Synthetic responsive layout",true);state.event(1000,new int[]{6291908},null,null);state.event(98,new int[]{mode==0?1:mode==1||mode==3?2:4},null,null);frame(3,mode==0?0x80:mode==1||mode==3?0x81:0x83,18);
  if(mode==0){state.event(115,new int[]{2},null,null);for(int i=0;i<6;i++)state.event(120+i,new int[]{new int[]{1,55,241,275,343,409}[i]},null,null);frame(4,2,0,241,3,0x81);}
  else {if(mode==3){frame(6,50,34,34);state.event(102,new int[]{0},null,null);}else{if(mode==1)frame(6,1,1,1);frame(5,2,0,1,1,0,0x15,0x02,0x34);}String title="A very long track name featuring another artist and an extended edition with additional text";int[] text=new int[title.length()+1];text[0]=mode==1?1:7;for(int i=0;i<title.length();i++)text[i+1]=title.charAt(i);frame(7,text);}
 }
 private Rect rect(View v){int[] xy=new int[2];v.getLocationOnScreen(xy);return new Rect(xy[0],xy[1],xy[0]+v.getWidth(),xy[1]+v.getHeight());}
 private void contained(View parent,View child,String name){if(child.getVisibility()!=View.VISIBLE)return;Rect actual=new Rect();boolean visible=child.getGlobalVisibleRect(actual);check(visible&&parent.getWidth()>0&&rect(parent).contains(rect(child))&&actual.equals(rect(child)),name+" is fully visible: "+rect(child)+" within "+rect(parent)+" actual "+actual);}
 private void noScroll(View v){check(!(v instanceof ScrollView)&&!(v instanceof HorizontalScrollView),"player has no scrolling container");if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)noScroll(g.getChildAt(i));}}
 private void verify(int width,int mode)throws Exception{View root=(View)field("playerRoot"),panel=activity.findViewById(android.R.id.content).findViewWithTag("player-information-panel"),metadata=(View)field("metadata");TextView primary=(TextView)field("primary");View illustration=(View)field("illustrationPanel");check(illustration.getVisibility()==(width<900?View.GONE:View.VISIBLE),"illustration follows activity width "+width);noScroll(root);contained(root,panel,"information panel");contained(metadata,primary,"title/frequency");contained(metadata,(View)field("elapsed"),"timer");contained(metadata,(View)field("details"),"playback context");if(mode!=0){contained(metadata,(View)field("titleRow"),"TITLE row");check(primary.getText().length()>40,"long title retained");check(primary.getLayout()!=null&&primary.getHeight()>=primary.getLayout().getHeight(),"title lines fit allocated height");}
  for(String name:new String[]{"select","previous","next"})contained(root,(View)field(name),name);for(String name:new String[]{"previous","next"}){TextView button=(TextView)field(name);check(button.getLayout()!=null&&button.getLayout().getLineCount()==1,name+" localized label stays on one line");check(button.getLayout().getEllipsisCount(0)==0,name+" localized label not ellipsized");check(button.getPaint().measureText(button.getText().toString())<=button.getWidth()-button.getCompoundPaddingLeft()-button.getCompoundPaddingRight(),name+" localized label fits button padding");}if(mode<2){View[] cards=(View[])field("presetCards");for(View card:cards)contained(panel,card,"preset/disc");check(cards[mode==0?2:1].isSelected(),"selected station/disc retained across resize");}check(!state.snapshot().commandBusy,"resizing sends no vehicle command");}
 private void image(Context c,String name)throws Exception{Bitmap screen=getUiAutomation().takeScreenshot();View root=(View)field("playerRoot");Rect[] bounds={null};runOnMainSync(()->bounds[0]=rect(root));Bitmap crop=Bitmap.createBitmap(screen,bounds[0].left,bounds[0].top,bounds[0].width(),bounds[0].height());try(java.io.OutputStream out=new java.io.FileOutputStream(new java.io.File(c.getExternalFilesDir(null),name))){crop.compress(Bitmap.CompressFormat.PNG,100,out);}crop.recycle();screen.recycle();}
 @Override public void onStart(){Context c=getTargetContext();String theme=ThemeSettings.mode(c),lang=I18n.language(c);Bundle result=new Bundle();int outcome=Activity.RESULT_OK;try{c.stopService(new Intent(c,ProbeService.class));SystemClock.sleep(400);for(String appearance:new String[]{ThemeSettings.DAY,ThemeSettings.NIGHT})for(String language:new String[]{"en","ru"})for(int mode=0;mode<4;mode++){
   ThemeSettings.mode(c,appearance);I18n.language(c,language);seed(mode);activity=startActivitySync(AudioPlayerActivity.intent(c,mode==0?AudioMode.RADIO:mode==1?AudioMode.CD:AudioMode.USB,false));SystemClock.sleep(500);LinearLayout root=(LinearLayout)field("playerRoot");float density=activity.getResources().getDisplayMetrics().density;
   for(int width:new int[]{1280,800,640,480,1280}){runOnMainSync(()->{ViewGroup.LayoutParams lp=root.getLayoutParams();lp.width=Math.round(width*density);root.setLayoutParams(lp);});SystemClock.sleep(220);final int m=mode;Throwable[] failure={null};runOnMainSync(()->{try{verify(width,m);}catch(Throwable e){failure[0]=e;}});if(failure[0]!=null)throw failure[0];if(language.equals("en")&&mode==1&&(width==640||width==1280))image(c,"responsive-cd-"+width+"-"+appearance+"-TEST.png");}
   if(mode==1&&root.getHeight()/density>=640){
    for(int width:new int[]{1280,640,480})for(int height:new int[]{400,640,400}){
     runOnMainSync(()->{ViewGroup.LayoutParams lp=root.getLayoutParams();lp.width=Math.round(width*density);lp.height=Math.round(height*density);root.setLayoutParams(lp);});SystemClock.sleep(250);
     Throwable[] failure={null};runOnMainSync(()->{try{
      verify(width,1);View[] cards=(View[])field("presetCards");boolean sameLine=rect(cards[0]).top==rect(cards[5]).top;check(sameLine==(height==400),"CD discs use one row at 400dp and two rows at 640dp");
      for(int i=0;i<6;i++){ViewGroup content=(ViewGroup)((ViewGroup)cards[i]).getChildAt(0);for(int j=0;j<content.getChildCount();j++)contained(cards[i],content.getChildAt(j),"disc glyph/label "+(i+1));}
     }catch(Throwable e){failure[0]=e;}});if(failure[0]!=null)throw failure[0];
     if(language.equals("en")&&width==640)image(c,"responsive-cd-640-height-"+height+"-"+appearance+"-TEST.png");
    }
   }
   runOnMainSync(()->activity.finish());waitForIdleSync();activity=null;
  }result.putString("result","PASS: "+checks+" responsive player layout checks; 4 sources, 2 themes, 2 languages, 1280/800/640/480dp and width/height resize restoration");
 }catch(Throwable e){outcome=1;result.putString("failure",android.util.Log.getStackTraceString(e));}finally{if(activity!=null)runOnMainSync(()->activity.finish());state.newSession();state.running(false);ThemeSettings.mode(c,theme);I18n.language(c,lang);}finish(outcome,result);}
}
